--
-- Name: control_approval_authorities(uuid, uuid); Type: FUNCTION; Schema: public; Owner: migration_admin
--

CREATE FUNCTION public.control_approval_authorities(p_company uuid, p_approval uuid) RETURNS TABLE(person_id text, role text, authority_kind text, platform_role text, is_active boolean, status text, suspended_at timestamp with time zone, company_status text, company_suspended_at timestamp with time zone, permissions jsonb, grant_valid boolean, current_scopes text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'auth', 'pg_temp'
    SET lock_timeout TO '5s'
    AS $$
DECLARE
  v_person text;
  v_request record;
  v_grant_valid boolean := false;
  v_current_scopes text[];
  v_caller_member boolean;
  v_caller_platform boolean;
BEGIN
  IF p_company IS DISTINCT FROM app.current_company_id() THEN
    RAISE EXCEPTION 'Approval authorities unavailable' USING ERRCODE='42501';
  END IF;
  SELECT a.* INTO v_request FROM public.control_operation_approvals a
    WHERE a.company_id=p_company AND a.id=p_approval;
  IF NOT FOUND THEN RAISE EXCEPTION 'Approval authorities unavailable' USING ERRCODE='42501'; END IF;

  SELECT EXISTS(SELECT 1 FROM public.company_users cu
    WHERE cu.company_id=p_company AND cu.user_id=auth.uid()::text) INTO v_caller_member;
  SELECT v_request.requester_auth_method='platform_import'
    AND v_request.requester_person_id=auth.uid()::text
    AND v_request.operation='historical_import.post' AND v_request.entity_type='historical_import'
    AND EXISTS(SELECT 1 FROM public.users pu WHERE pu.id=v_request.requester_person_id AND pu.role='super_admin')
    AND EXISTS(SELECT 1 FROM public.control_historical_imports hi
      WHERE hi.company_id=p_company AND hi.id=v_request.entity_id::uuid
        AND hi.requester_person_id=v_request.requester_person_id
        AND hi.requester_auth_method='platform_import') INTO v_caller_platform;
  IF NOT v_caller_member AND NOT v_caller_platform THEN
    RAISE EXCEPTION 'Approval authorities unavailable' USING ERRCODE='42501';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('control-authority:' || p_company::text,0));
  FOR v_person IN SELECT DISTINCT ids.id FROM (
    SELECT auth.uid()::text AS id UNION ALL SELECT v_request.requester_person_id UNION ALL
    SELECT d.person_id FROM public.control_operation_decisions d
      WHERE d.company_id=p_company AND d.approval_id=p_approval
  ) ids WHERE ids.id IS NOT NULL ORDER BY ids.id LOOP
    PERFORM 1 FROM public.users u WHERE u.id=v_person FOR UPDATE;
    PERFORM 1 FROM public.company_users cu WHERE cu.company_id=p_company AND cu.user_id=v_person FOR UPDATE;
    PERFORM 1 FROM public.company_user_permissions cp
      WHERE cp.company_id=p_company AND cp.user_id=v_person ORDER BY cp.module_key FOR SHARE;
  END LOOP;
  PERFORM 1 FROM public.companies c WHERE c.id=p_company FOR SHARE;

  IF v_request.requester_auth_method='cookie' THEN v_grant_valid := true;
  ELSIF v_request.requester_auth_method='platform_import' THEN
    v_grant_valid := EXISTS(SELECT 1 FROM public.users u
      WHERE u.id=v_request.requester_person_id AND u.role='super_admin');
  ELSIF v_request.requester_auth_method='pat' THEN
    SELECT g.revoked_at IS NULL AND g.expires_at>clock_timestamp(),g.scopes INTO v_grant_valid,v_current_scopes
      FROM public.personal_access_tokens g WHERE g.company_id=p_company
        AND g.user_id=v_request.requester_person_id AND g.id=v_request.requester_grant_id FOR SHARE;
  ELSIF v_request.requester_auth_method='oauth' THEN
    SELECT g.revoked_at IS NULL AND g.access_token_expires_at>clock_timestamp(),g.scopes INTO v_grant_valid,v_current_scopes
      FROM public.oauth_authorisations g WHERE g.company_id=p_company
        AND g.user_id=v_request.requester_person_id AND g.id=v_request.requester_grant_id FOR SHARE;
  END IF;
  IF v_request.requester_auth_method IN('pat','oauth') THEN
    SELECT COALESCE(array_agg(scope),ARRAY[]::text[]) INTO v_current_scopes FROM unnest(v_current_scopes) scope
      WHERE scope=ANY(v_request.requester_granted_scopes);
  END IF;

  RETURN QUERY SELECT DISTINCT u.id::text,
    CASE WHEN v_request.requester_auth_method='platform_import' AND u.id=v_request.requester_person_id
      THEN NULL::text ELSE cu.role::text END,
    CASE WHEN v_request.requester_auth_method='platform_import' AND u.id=v_request.requester_person_id
      THEN 'platform_import'::text ELSE 'member'::text END,
    CASE WHEN v_request.requester_auth_method='platform_import' AND u.id=v_request.requester_person_id
      THEN u.role::text ELSE NULL::text END,
    u.is_active,u.status::text,u.suspended_at,c.status::text,c.suspended_at,
    CASE WHEN cu.user_id IS NULL THEN '[]'::jsonb ELSE COALESCE((SELECT jsonb_agg(to_jsonb(cp) ORDER BY cp.module_key)
      FROM public.company_user_permissions cp WHERE cp.company_id=p_company AND cp.user_id=u.id),'[]'::jsonb) END,
    CASE WHEN u.id=v_request.requester_person_id THEN COALESCE(v_grant_valid,false) ELSE cu.user_id IS NOT NULL END,
    CASE WHEN u.id=v_request.requester_person_id THEN v_current_scopes ELSE NULL::text[] END
  FROM (
    SELECT auth.uid()::text AS bound_id UNION SELECT v_request.requester_person_id UNION
    SELECT d.person_id FROM public.control_operation_decisions d
      WHERE d.company_id=p_company AND d.approval_id=p_approval
  ) bound
  JOIN public.users u ON u.id=bound.bound_id
  CROSS JOIN public.companies c
  LEFT JOIN public.company_users cu ON cu.user_id=u.id AND cu.company_id=p_company
  WHERE c.id=p_company AND (cu.user_id IS NOT NULL OR
    (v_request.requester_auth_method='platform_import' AND u.id=v_request.requester_person_id AND u.role='super_admin'));
END;
$$;


ALTER FUNCTION public.control_approval_authorities(p_company uuid, p_approval uuid) OWNER TO migration_admin;

--
-- Name: control_beneficiary_authorities(uuid, uuid); Type: FUNCTION; Schema: public; Owner: migration_admin
--

CREATE FUNCTION public.control_beneficiary_authorities(p_company uuid, p_approval uuid) RETURNS TABLE(person_id text, role text, is_active boolean, status text, suspended_at timestamp with time zone, company_status text, company_suspended_at timestamp with time zone, permissions jsonb, grant_valid boolean, current_scopes text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'auth'
    SET lock_timeout TO '5s'
    AS $$
DECLARE v_person text; v_request record; v_grant_valid boolean := false; v_current_scopes text[];
BEGIN
  IF p_company IS DISTINCT FROM app.current_company_id() OR NOT EXISTS(
    SELECT 1 FROM public.company_users cu WHERE cu.company_id=p_company AND cu.user_id=auth.uid()::text
  ) OR NOT EXISTS(SELECT 1 FROM public.control_beneficiary_proposals a WHERE a.company_id=p_company AND a.id=p_approval) THEN
    RAISE EXCEPTION 'Approval authorities unavailable' USING ERRCODE='42501';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('control-authority:' || p_company::text,0));
  -- Lock the complete participant population only after the authority serialization lock.
  FOR v_person IN SELECT DISTINCT ids.id FROM (
    SELECT auth.uid()::text AS id UNION ALL
    SELECT a.requester_person_id FROM public.control_beneficiary_proposals a WHERE a.company_id=p_company AND a.id=p_approval
  ) ids ORDER BY ids.id LOOP
    PERFORM 1 FROM public.users u WHERE u.id=v_person FOR UPDATE;
    PERFORM 1 FROM public.company_users cu WHERE cu.company_id=p_company AND cu.user_id=v_person FOR UPDATE;
    PERFORM 1 FROM public.company_user_permissions cp WHERE cp.company_id=p_company AND cp.user_id=v_person
      ORDER BY cp.module_key FOR SHARE;
  END LOOP;
  PERFORM 1 FROM public.companies c WHERE c.id=p_company FOR SHARE;
  SELECT a.* INTO v_request FROM public.control_beneficiary_proposals a WHERE a.company_id=p_company AND a.id=p_approval;
  IF v_request.requester_auth_method='cookie' THEN v_grant_valid := true;
  ELSIF v_request.requester_auth_method='pat' THEN
    SELECT g.revoked_at IS NULL AND g.expires_at > clock_timestamp(),g.scopes INTO v_grant_valid,v_current_scopes
      FROM public.personal_access_tokens g WHERE g.company_id=p_company AND g.user_id=v_request.requester_person_id
        AND g.id=v_request.requester_grant_id FOR SHARE;
  ELSIF v_request.requester_auth_method='oauth' THEN
    SELECT g.revoked_at IS NULL AND g.access_token_expires_at > clock_timestamp(),g.scopes INTO v_grant_valid,v_current_scopes
      FROM public.oauth_authorisations g WHERE g.company_id=p_company AND g.user_id=v_request.requester_person_id
        AND g.id=v_request.requester_grant_id FOR SHARE;
  END IF;
  IF v_request.requester_auth_method <> 'cookie' THEN
    SELECT COALESCE(array_agg(scope),ARRAY[]::text[]) INTO v_current_scopes FROM unnest(v_current_scopes) scope
      WHERE scope=ANY(v_request.requester_granted_scopes);
  END IF;

  RETURN QUERY SELECT DISTINCT u.id::text,cu.role::text,u.is_active,u.status::text,u.suspended_at,
    c.status::text,c.suspended_at,COALESCE((SELECT jsonb_agg(to_jsonb(cp) ORDER BY cp.module_key)
      FROM public.company_user_permissions cp WHERE cp.company_id=p_company AND cp.user_id=u.id),'[]'::jsonb),
    CASE WHEN u.id=v_request.requester_person_id THEN COALESCE(v_grant_valid,false) ELSE true END,
    CASE WHEN u.id=v_request.requester_person_id THEN v_current_scopes ELSE NULL::text[] END
    FROM (
      SELECT auth.uid()::text AS person_id UNION
      SELECT a.requester_person_id FROM public.control_beneficiary_proposals a WHERE a.company_id=p_company AND a.id=p_approval
    ) bound
    JOIN public.users u ON u.id=bound.person_id
    JOIN public.company_users cu ON cu.user_id=u.id AND cu.company_id=p_company
    JOIN public.companies c ON c.id=cu.company_id
    WHERE cu.company_id=p_company;
END;
$$;


ALTER FUNCTION public.control_beneficiary_authorities(p_company uuid, p_approval uuid) OWNER TO migration_admin;

--
-- Name: control_customer_payment_allocations_history(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.control_customer_payment_allocations_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE owned_company uuid;
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.application_intent_id IS NOT NULL THEN RAISE EXCEPTION 'Controlled allocation history cannot be deleted'; END IF;
  RETURN OLD;
 END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.application_intent_id IS DISTINCT FROM NEW.application_intent_id THEN
   RAISE EXCEPTION 'Allocation intent cannot be reassigned';
  END IF;
  IF OLD.application_intent_id IS NOT NULL AND
   (to_jsonb(OLD)-'reversed_at'-'reversal_intent_id') IS DISTINCT FROM (to_jsonb(NEW)-'reversed_at'-'reversal_intent_id') THEN
   RAISE EXCEPTION 'Controlled allocation history is immutable';
  END IF;
  IF OLD.reversed_at IS NOT NULL AND
   (OLD.reversed_at IS DISTINCT FROM NEW.reversed_at OR OLD.reversal_intent_id IS DISTINCT FROM NEW.reversal_intent_id) THEN
   RAISE EXCEPTION 'Allocation reversal is immutable';
  END IF;
 END IF;
 IF (NEW.reversed_at IS NULL)<>(NEW.reversal_intent_id IS NULL) THEN
  RAISE EXCEPTION 'Allocation reversal requires paired lineage';
 END IF;
 IF NEW.application_intent_id IS NULL THEN
  IF NEW.reversed_at IS NOT NULL THEN RAISE EXCEPTION 'Legacy allocation cannot acquire controlled inverse'; END IF;
  RETURN NEW;
 END IF;
 IF TG_OP='INSERT' AND NEW.reversed_at IS NOT NULL THEN RAISE EXCEPTION 'New allocation must be active'; END IF;
 SELECT p.company_id INTO owned_company FROM public.customer_payments p
 JOIN public.customer_invoices i ON i.company_id=p.company_id AND i.id=NEW.invoice_id
 JOIN public.control_cash_application_intents a ON a.company_id=p.company_id AND a.id=NEW.application_intent_id
  AND a.payment_id=p.id AND a.kind='customer'
 WHERE p.id=NEW.payment_id;
 IF owned_company IS NULL THEN RAISE EXCEPTION 'Allocation intent, payment and invoice must share ownership'; END IF;
 IF NEW.reversal_intent_id IS NOT NULL AND NOT EXISTS(
  SELECT 1 FROM public.control_cash_application_reversal_intents r
  WHERE r.company_id=owned_company AND r.id=NEW.reversal_intent_id AND r.original_intent_id=NEW.application_intent_id
 ) THEN RAISE EXCEPTION 'Allocation inverse must reference its original intent'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION public.control_customer_payment_allocations_history() OWNER TO postgres;

--
-- Name: control_exception_owner(uuid, text); Type: FUNCTION; Schema: public; Owner: migration_admin
--

CREATE FUNCTION public.control_exception_owner(p_company uuid, p_owner text) RETURNS TABLE(user_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'auth'
    SET lock_timeout TO '5s'
    AS $$
BEGIN
 IF p_company IS DISTINCT FROM app.current_company_id() OR auth.uid() IS NULL THEN
  RAISE EXCEPTION 'Exception owner unavailable' USING ERRCODE='42501';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('control-authority:' || p_company::text,0));
 IF NOT EXISTS(
  SELECT 1 FROM public.company_users member JOIN public.users caller ON caller.id=member.user_id
  JOIN public.companies company ON company.id=member.company_id
  WHERE member.company_id=p_company AND member.user_id=auth.uid()::text
   AND caller.is_active=true AND caller.suspended_at IS NULL AND (caller.status IS NULL OR lower(caller.status)='active')
   AND company.suspended_at IS NULL AND (company.status IS NULL OR company.status NOT IN('suspended','deleted'))
 ) THEN RETURN; END IF;
 RETURN QUERY SELECT member.user_id::text FROM public.company_users member
  JOIN public.users owner_user ON owner_user.id=member.user_id
  WHERE member.company_id=p_company AND member.user_id=p_owner AND owner_user.is_active=true
   AND owner_user.suspended_at IS NULL AND (owner_user.status IS NULL OR lower(owner_user.status)='active')
  FOR SHARE OF member,owner_user;
END;
$$;


ALTER FUNCTION public.control_exception_owner(p_company uuid, p_owner text) OWNER TO migration_admin;

--
-- Name: control_guard_approval_birth(); Type: FUNCTION; Schema: public; Owner: migration_admin
--

CREATE FUNCTION public.control_guard_approval_birth() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_actor text := auth.uid()::text;
BEGIN
  IF v_actor IS NULL OR NEW.requester_person_id IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'Approval birth refused: the requester must be the acting person' USING ERRCODE='23514';
  END IF;
  IF NEW.decided_at IS NOT NULL OR NEW.consumed_at IS NOT NULL OR NEW.consumed_effect_id IS NOT NULL
    -- IS NOT DISTINCT FROM: a binding with no policies key, or a null one, is refused, never read as empty.
    OR NOT (NEW.status = 'pending' OR (NEW.status = 'approved' AND NEW.binding->'policies' IS NOT DISTINCT FROM '[]'::jsonb)) THEN
    RAISE EXCEPTION 'Approval birth refused: an approval is born pending, or approved only when no policy binds it'
      USING ERRCODE='23514';
  END IF;
  NEW.requested_at := clock_timestamp();
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.control_guard_approval_birth() OWNER TO migration_admin;

--
-- Name: control_guard_approval_transition(); Type: FUNCTION; Schema: public; Owner: migration_admin
--

CREATE FUNCTION public.control_guard_approval_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  -- entity_id_canonical is generated from entity_id, and is not yet computed in a BEFORE trigger.
  v_moving CONSTANT text[] := ARRAY['status','decided_at','consumed_at','consumed_effect_id','entity_id_canonical'];
  v_actor text := auth.uid()::text;
BEGIN
  IF (to_jsonb(NEW) - v_moving) IS DISTINCT FROM (to_jsonb(OLD) - v_moving) THEN
    RAISE EXCEPTION 'Approval transition refused: identity, binding, requester and expiry are immutable' USING ERRCODE='23514';
  END IF;
  IF OLD.status IN ('rejected','cancelled','consumed') THEN
    IF (to_jsonb(NEW) - 'entity_id_canonical') IS DISTINCT FROM (to_jsonb(OLD) - 'entity_id_canonical') THEN
      RAISE EXCEPTION 'Approval transition refused: % is terminal', OLD.status USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.status <> 'consumed' AND (NEW.consumed_at IS NOT NULL OR NEW.consumed_effect_id IS NOT NULL) THEN
    RAISE EXCEPTION 'Approval transition refused: only consumption records an effect' USING ERRCODE='23514';
  END IF;
  IF NEW.status = OLD.status AND NEW.decided_at IS NOT DISTINCT FROM OLD.decided_at THEN RETURN NEW; END IF;
  IF (OLD.status, NEW.status) NOT IN (('pending','pending'),('pending','approved'),('pending','rejected'),
    ('pending','cancelled'),('approved','cancelled'),('approved','consumed')) THEN
    RAISE EXCEPTION 'Approval transition refused: % to %', OLD.status, NEW.status USING ERRCODE='23514';
  END IF;
  IF OLD.expires_at <= clock_timestamp() THEN
    RAISE EXCEPTION 'Approval transition refused: the approval has expired' USING ERRCODE='23514';
  END IF;

  IF NEW.status = 'consumed' THEN
    IF NEW.decided_at IS DISTINCT FROM OLD.decided_at OR NOT EXISTS(SELECT 1 FROM public.control_operation_effects e
        WHERE e.company_id=NEW.company_id AND e.id=NEW.consumed_effect_id AND e.operation_id=NEW.operation_id
          AND e.operation=NEW.operation AND e.entity_type=NEW.entity_type AND e.entity_id_canonical=OLD.entity_id_canonical
          AND e.binding_hash=NEW.binding_hash AND e.committed_at BETWEEN transaction_timestamp() AND clock_timestamp())
      OR EXISTS(SELECT 1 FROM public.control_operation_approvals a
        WHERE a.company_id=NEW.company_id AND a.consumed_effect_id=NEW.consumed_effect_id AND a.id<>NEW.id) THEN
      RAISE EXCEPTION 'Approval transition refused: consumption must name the effect this execution committed'
        USING ERRCODE='23514';
    END IF;
    NEW.consumed_at := clock_timestamp();
    RETURN NEW;
  END IF;

  -- Every other edge is a decision, and it is the acting person's.
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Approval transition refused: a decision needs an acting person' USING ERRCODE='23514';
  END IF;
  IF NEW.status = 'cancelled' THEN
    IF v_actor <> OLD.requester_person_id THEN
      RAISE EXCEPTION 'Approval transition refused: only the requester can cancel' USING ERRCODE='23514';
    END IF;
  ELSIF NOT EXISTS(SELECT 1 FROM public.control_operation_decisions d
      WHERE d.company_id=NEW.company_id AND d.approval_id=NEW.id AND d.person_id=v_actor
        AND d.decided_at >= transaction_timestamp()
        AND d.decision = CASE WHEN NEW.status = 'rejected' THEN 'rejected' ELSE 'approved' END) THEN
    RAISE EXCEPTION 'Approval transition refused: the acting person recorded no such decision in this transaction'
      USING ERRCODE='23514';
  -- The rule validateDecisions applies at execution. A binding without a policy array cannot be judged.
  ELSIF NEW.status = 'approved' AND (jsonb_typeof(NEW.binding->'policies') IS DISTINCT FROM 'array'
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.binding->'policies') p
      WHERE NOT EXISTS(SELECT 1 FROM public.control_operation_decisions d WHERE d.company_id=NEW.company_id
        AND d.approval_id=NEW.id AND d.policy_id=p->>'policyId' AND d.decision='approved'
        AND d.person_id<>NEW.requester_person_id))) THEN
    RAISE EXCEPTION 'Approval transition refused: approval requires an independent decision for every policy'
      USING ERRCODE='23514';
  END IF;
  NEW.decided_at := clock_timestamp();
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.control_guard_approval_transition() OWNER TO migration_admin;

