--
-- Name: control_guard_decision_insert(); Type: FUNCTION; Schema: public; Owner: migration_admin
--

CREATE FUNCTION public.control_guard_decision_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_actor text := auth.uid()::text; v_approval record;
BEGIN
  IF v_actor IS NULL OR NEW.person_id IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'Approval decision refused: the decider must be the acting person' USING ERRCODE='23514';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.company_users cu WHERE cu.company_id=NEW.company_id AND cu.user_id::text=v_actor) THEN
    RAISE EXCEPTION 'Approval decision refused: the decider must be a member of the company' USING ERRCODE='23514';
  END IF;
  SELECT a.status,a.requester_person_id,a.binding,a.expires_at INTO v_approval FROM public.control_operation_approvals a
    WHERE a.company_id=NEW.company_id AND a.id=NEW.approval_id FOR SHARE;
  IF NOT FOUND OR v_approval.status <> 'pending' OR v_approval.expires_at <= clock_timestamp() THEN
    RAISE EXCEPTION 'Approval decision refused: a decision lands only on a pending, unexpired approval' USING ERRCODE='23514';
  END IF;
  IF v_approval.requester_person_id = v_actor THEN
    RAISE EXCEPTION 'Approval decision refused: the requester cannot decide their own approval' USING ERRCODE='23514';
  END IF;
  IF jsonb_typeof(v_approval.binding->'policies') IS DISTINCT FROM 'array' OR NOT EXISTS(
    SELECT 1 FROM jsonb_array_elements(v_approval.binding->'policies') p WHERE p->>'policyId' = NEW.policy_id) THEN
    RAISE EXCEPTION 'Approval decision refused: the policy is not bound to this approval' USING ERRCODE='23514';
  END IF;
  NEW.decided_at := clock_timestamp();
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.control_guard_decision_insert() OWNER TO migration_admin;

--
-- Name: control_lock_approval_policy_statement(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.control_lock_approval_policy_statement() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'app'
    AS $$
DECLARE v_company uuid := app.current_company_id();
BEGIN
  IF v_company IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('control-policy:' || v_company::text,0));
  ELSIF current_user = 'app_user' THEN
    RAISE EXCEPTION 'Authenticated policy tenant required' USING ERRCODE='42501';
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.control_lock_approval_policy_statement() OWNER TO postgres;

--
-- Name: control_lock_permission_principal(uuid, text); Type: FUNCTION; Schema: public; Owner: migration_admin
--

CREATE FUNCTION public.control_lock_permission_principal(p_company uuid, p_person text) RETURNS TABLE(role text, account_user_id text, is_active boolean, status text, suspended_at timestamp with time zone, company_status text, company_suspended_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'auth'
    SET lock_timeout TO '5s'
    AS $$
BEGIN
  IF p_company IS DISTINCT FROM app.current_company_id()
    OR p_person IS DISTINCT FROM auth.uid()::text THEN
    RAISE EXCEPTION 'Control principal unavailable' USING ERRCODE = '42501';
  END IF;
  -- All control authority readers enter before person locks to avoid participant inversion.
  PERFORM pg_advisory_xact_lock(hashtextextended('control-authority:' || p_company::text,0));
  RETURN QUERY
    SELECT cu.role::text, u.id::text, u.is_active, u.status::text, u.suspended_at,
      c.status::text, c.suspended_at
    FROM public.company_users cu
    JOIN public.users u ON u.id = cu.user_id
    JOIN public.companies c ON c.id = cu.company_id
    WHERE cu.company_id = p_company AND cu.user_id = p_person
    FOR UPDATE OF cu, u FOR SHARE OF c;
END;
$$;


ALTER FUNCTION public.control_lock_permission_principal(p_company uuid, p_person text) OWNER TO migration_admin;

