--
-- Name: control_seed_statement_policy(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.control_seed_statement_policy() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
 INSERT INTO public.control_mandatory_statement_policies(company_id) VALUES(NEW.id) ON CONFLICT(company_id) DO NOTHING;
 RETURN NEW;
END $$;


