--
-- Name: control_session_impersonator(); Type: FUNCTION; Schema: public; Owner: migration_admin
--

CREATE FUNCTION public.control_session_impersonator() RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth', 'pg_temp'
    AS $$
DECLARE v_actor text;
BEGIN
  IF NOT public.impersonation_evidence_visible() THEN RETURN 'impersonation-state-unverified'; END IF;
  SELECT l.admin_user_id::text INTO v_actor FROM public.admin_audit_log l
    WHERE l.action='impersonation_start' AND l.target_type='user'
      AND l.target_id::text=auth.uid()
      AND l.details->>'target_session_id'=
        (nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'session_id')
    ORDER BY l.created_at DESC LIMIT 1;
  RETURN v_actor;
END;
$$;


ALTER FUNCTION public.control_session_impersonator() OWNER TO migration_admin;

--
-- Name: control_version_approval_policy(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.control_version_approval_policy() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.company_id IS DISTINCT FROM OLD.company_id THEN
    RAISE EXCEPTION 'Approval policy tenant cannot change';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('control-policy:' ||
    CASE WHEN TG_OP = 'DELETE' THEN OLD.company_id ELSE NEW.company_id END::text, 0));
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  IF (NEW.aggregate_window_days IS NOT NULL AND NEW.aggregate_window_days <> 1)
    OR (NEW.aggregate_by IS NOT NULL AND NEW.aggregate_by <> 'supplier')
    OR ((NEW.aggregate_window_days IS NULL) <> (NEW.aggregate_by IS NULL)) THEN
    RAISE EXCEPTION 'Unsupported aggregate approval policy';
  END IF;
  IF TG_OP = 'INSERT' THEN NEW.control_version := 1;
  ELSIF (to_jsonb(NEW) - 'control_version' - 'updated_at') IS DISTINCT FROM
    (to_jsonb(OLD) - 'control_version' - 'updated_at') THEN NEW.control_version := OLD.control_version + 1;
  ELSE NEW.control_version := OLD.control_version;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.control_version_approval_policy() OWNER TO postgres;

