--
-- Name: generate_adjustment_number(); Type: FUNCTION; Schema: public; Owner: migration_admin
--

CREATE FUNCTION public.generate_adjustment_number() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  adj_year INT;
  next_seq INT;
BEGIN
  IF NEW.adjustment_number IS NOT NULL THEN
    RETURN NEW;
  END IF;
  adj_year := EXTRACT(YEAR FROM CURRENT_DATE);
  SELECT COALESCE(MAX(
    CAST(NULLIF(SPLIT_PART(adjustment_number, '-', 3), '') AS INT)
  ), 0) + 1 INTO next_seq
  FROM accounting_adjustments
  WHERE company_id = NEW.company_id
    AND adjustment_number LIKE 'ADJ-' || adj_year || '-%';
  NEW.adjustment_number := 'ADJ-' || adj_year || '-' || LPAD(next_seq::TEXT, 5, '0');
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.generate_adjustment_number() OWNER TO migration_admin;

