--
-- Name: get_trial_balance(uuid); Type: FUNCTION; Schema: public; Owner: migration_admin
--

CREATE FUNCTION public.get_trial_balance(p_fiscal_period_id uuid) RETURNS TABLE(account_code character varying, account_name character varying, account_type character varying, normal_balance character varying, debit_balance numeric, credit_balance numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    a.account_code,
    a.account_name,
    a.account_type,
    a.normal_balance,
    COALESCE(b.debit_total, 0) AS debit_balance,
    COALESCE(b.credit_total, 0) AS credit_balance
  FROM gl_accounts a
  LEFT JOIN gl_account_balances b ON b.gl_account_id = a.id AND b.fiscal_period_id = p_fiscal_period_id
  WHERE a.is_active = true
    AND (b.debit_total > 0 OR b.credit_total > 0)
  ORDER BY a.account_code;
END;
$$;


ALTER FUNCTION public.get_trial_balance(p_fiscal_period_id uuid) OWNER TO migration_admin;

--
-- Name: gl_accounts_normalise_subtype(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gl_accounts_normalise_subtype() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.account_subtype IS NOT NULL THEN
    -- The SQL twin of canonicalSubtype's
    -- raw.trim().toLowerCase().replace(/[\s-]+/g, '_'). A value that is only
    -- whitespace collapses to '' there and returns null; NULLIF reproduces it.
    NEW.account_subtype := NULLIF(
      lower(regexp_replace(btrim(NEW.account_subtype), '[[:space:]-]+', '_', 'g')),
      ''
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.gl_accounts_normalise_subtype() OWNER TO postgres;

