--
-- Name: practice_pcro_mirror_columns(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.practice_pcro_mirror_columns() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    -- Carry whichever side the statement actually changed over to the other.
    IF NEW.rate_per_hour IS DISTINCT FROM OLD.rate_per_hour THEN
      NEW.rate := NEW.rate_per_hour;
    ELSIF NEW.rate IS DISTINCT FROM OLD.rate THEN
      NEW.rate_per_hour := NEW.rate;
    END IF;
    IF NEW.staff_user_id IS DISTINCT FROM OLD.staff_user_id THEN
      NEW.user_id := NEW.staff_user_id;
    ELSIF NEW.user_id IS DISTINCT FROM OLD.user_id THEN
      NEW.staff_user_id := NEW.user_id;
    END IF;
    NEW.staff_user_id := COALESCE(NEW.staff_user_id, NEW.user_id);
    NEW.user_id       := COALESCE(NEW.user_id, NEW.staff_user_id);
    NEW.rate_per_hour := COALESCE(NEW.rate_per_hour, NEW.rate);
    NEW.rate          := COALESCE(NEW.rate, NEW.rate_per_hour);
  ELSE
    -- INSERT: there is no OLD row to say which side the writer meant, so the newer
    -- column is authoritative. This fills a legacy half left NULL and also reconciles
    -- two halves supplied together that disagree, which would otherwise pass through.
    NEW.staff_user_id := COALESCE(NEW.staff_user_id, NEW.user_id);
    NEW.rate_per_hour := COALESCE(NEW.rate_per_hour, NEW.rate);
    NEW.user_id       := NEW.staff_user_id;
    NEW.rate          := NEW.rate_per_hour;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.practice_pcro_mirror_columns() OWNER TO postgres;

--
-- Name: refresh_gl_account_balances_on_status_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_gl_account_balances_on_status_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  acct UUID;
  per  UUID;
BEGIN
  -- Recompute each account this entry touches from posted lines only, so the
  -- cache equals the reporting truth regardless of which way the status moved
  -- (draft->posted adds the entry's lines, posted->reversed/draft removes them).
  -- This fires once per status change (not once per line), so a full recompute
  -- per affected account stays O(lines-in-account-for-period) and avoids the
  -- O(N^2) blow-up that pushed mig 465's line trigger to incremental deltas.
  --
  -- Recompute under BOTH the new and old fiscal period: if a single UPDATE ever
  -- changes status AND fiscal_period_id together, the entry's contribution is
  -- removed from the old period and rebuilt under the new one (no stale row).
  -- Entries with no fiscal period cannot be cached (keyed on fiscal_period_id),
  -- so NULL periods are skipped.
  --
  -- NOTE: the aggregate SELECT has no GROUP BY, so when no posted lines remain
  -- for (acct, per) it still returns one row of zeros — the ON CONFLICT upsert
  -- then sets the cached balance to 0 rather than leaving a stale value.
  FOR per IN
    SELECT DISTINCT p
    FROM unnest(ARRAY[NEW.fiscal_period_id, OLD.fiscal_period_id]) AS u(p)
    WHERE p IS NOT NULL
  LOOP
    FOR acct IN
      SELECT DISTINCT gl_account_id FROM gl_journal_lines WHERE journal_entry_id = NEW.id
    LOOP
      INSERT INTO gl_account_balances (gl_account_id, fiscal_period_id, debit_total, credit_total, balance)
      SELECT
        acct, per,
        COALESCE(SUM(jl.debit), 0),
        COALESCE(SUM(jl.credit), 0),
        COALESCE(SUM(jl.debit), 0) - COALESCE(SUM(jl.credit), 0)
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      WHERE jl.gl_account_id = acct
        AND je.fiscal_period_id = per
        AND je.status = 'posted'
      ON CONFLICT (gl_account_id, fiscal_period_id) DO UPDATE SET
        debit_total = EXCLUDED.debit_total,
        credit_total = EXCLUDED.credit_total,
        balance = EXCLUDED.balance,
        updated_at = NOW();
    END LOOP;
  END LOOP;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.refresh_gl_account_balances_on_status_change() OWNER TO postgres;

--
-- Name: resolve_je_fiscal_period(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_je_fiscal_period() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.fiscal_period_id IS NULL THEN
    SELECT fp.id INTO NEW.fiscal_period_id
    FROM fiscal_periods fp
    WHERE fp.company_id = NEW.company_id
      AND NEW.entry_date BETWEEN fp.start_date AND fp.end_date
    ORDER BY fp.start_date
    LIMIT 1;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.resolve_je_fiscal_period() OWNER TO postgres;

