--
-- Name: customer_invoice_view_summary; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.customer_invoice_view_summary AS
 SELECT customer_invoice_id,
    company_id,
    max(viewed_at) AS last_viewed_at,
    count(*) AS view_count,
    count(DISTINCT session_token) FILTER (WHERE (session_token IS NOT NULL)) AS distinct_sessions
   FROM public.customer_invoice_views
  GROUP BY customer_invoice_id, company_id
  WITH NO DATA;


