--
-- Name: mcp_invocation_attempts authenticated_admission; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY authenticated_admission ON public.mcp_invocation_attempts FOR INSERT WITH CHECK (((company_id = app.current_company_id()) AND (person_id = auth.uid())));


--
-- Name: mcp_invocation_outcomes authenticated_outcome; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY authenticated_outcome ON public.mcp_invocation_outcomes FOR INSERT WITH CHECK (((company_id = app.current_company_id()) AND (EXISTS ( SELECT 1
   FROM public.mcp_invocation_attempts a
  WHERE ((a.company_id = mcp_invocation_outcomes.company_id) AND (a.id = mcp_invocation_outcomes.attempt_id) AND ((a.person_id = auth.uid()) OR ((mcp_invocation_outcomes.source = 'reconciled'::text) AND (a.company_id IN ( SELECT auth.user_companies() AS user_companies)))))))));


