--
-- Name: control_audit_check_findings current_check_run_worker; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY current_check_run_worker ON public.control_audit_check_findings FOR INSERT WITH CHECK (((company_id = app.current_company_id()) AND (company_id IN ( SELECT auth.user_companies() AS user_companies)) AND (EXISTS ( SELECT 1
   FROM (public.control_audit_jobs j
     JOIN public.control_audit_job_intents i ON (((i.company_id = j.company_id) AND (i.id = j.job_id))))
  WHERE ((j.company_id = control_audit_check_findings.company_id) AND (j.job_id = control_audit_check_findings.job_id) AND (j.generation = control_audit_check_findings.generation) AND (j.lease_id = control_audit_check_findings.lease_id) AND (j.state = 'running'::text) AND (j.lease_expires_at > clock_timestamp()) AND (i.kind = 'audit_check_run'::text) AND (i.requester_person_id = auth.uid()))))));


--
-- Name: control_audit_check_results current_check_run_worker; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY current_check_run_worker ON public.control_audit_check_results FOR INSERT WITH CHECK (((company_id = app.current_company_id()) AND (company_id IN ( SELECT auth.user_companies() AS user_companies)) AND (EXISTS ( SELECT 1
   FROM (public.control_audit_jobs j
     JOIN public.control_audit_job_intents i ON (((i.company_id = j.company_id) AND (i.id = j.job_id))))
  WHERE ((j.company_id = control_audit_check_results.company_id) AND (j.job_id = control_audit_check_results.job_id) AND (j.generation = control_audit_check_results.generation) AND (j.lease_id = control_audit_check_results.lease_id) AND (j.state = 'running'::text) AND (j.lease_expires_at > clock_timestamp()) AND (i.kind = 'audit_check_run'::text) AND (i.requester_person_id = auth.uid()))))));


