--
-- Name: mcp_invocation_receipts original_transaction; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY original_transaction ON public.mcp_invocation_receipts FOR INSERT WITH CHECK (((company_id = app.current_company_id()) AND (outer_xid = pg_current_xact_id()) AND (EXISTS ( SELECT 1
   FROM public.mcp_invocation_attempts a
  WHERE ((a.company_id = mcp_invocation_receipts.company_id) AND (a.id = mcp_invocation_receipts.attempt_id) AND (a.person_id = auth.uid()) AND (a.outer_xid = mcp_invocation_receipts.outer_xid))))));


