--

CREATE POLICY tenant_create ON public.control_audit_snapshot_artifacts FOR INSERT WITH CHECK (((company_id = app.current_company_id()) AND (company_id IN ( SELECT auth.user_companies() AS user_companies)) AND (EXISTS ( SELECT 1
   FROM public.control_audit_snapshots s
  WHERE ((s.company_id = control_audit_snapshot_artifacts.company_id) AND (s.id = control_audit_snapshot_artifacts.snapshot_id) AND (s.requester_person_id = auth.uid()))))));


--
-- Name: control_audit_snapshot_index_chunks tenant_create; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY tenant_create ON public.control_audit_snapshot_index_chunks FOR INSERT WITH CHECK (((company_id = app.current_company_id()) AND (company_id IN ( SELECT auth.user_companies() AS user_companies)) AND (EXISTS ( SELECT 1
   FROM ((public.control_audit_snapshot_indexes h
     JOIN public.control_audit_jobs j ON (((j.company_id = h.company_id) AND (j.job_id = h.build_job_id))))
     JOIN public.control_audit_job_intents i ON (((i.company_id = j.company_id) AND (i.id = j.job_id))))
  WHERE ((h.company_id = control_audit_snapshot_index_chunks.company_id) AND (h.snapshot_id = control_audit_snapshot_index_chunks.snapshot_id) AND (j.state = 'running'::text) AND (j.generation = h.build_generation) AND (j.lease_id = h.build_lease_id) AND (j.lease_expires_at > clock_timestamp()) AND (i.requester_person_id = auth.uid()))))));


--
-- Name: control_audit_snapshot_index_items tenant_create; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY tenant_create ON public.control_audit_snapshot_index_items FOR INSERT WITH CHECK (((company_id = app.current_company_id()) AND (company_id IN ( SELECT auth.user_companies() AS user_companies)) AND (EXISTS ( SELECT 1
   FROM ((public.control_audit_snapshot_indexes h
     JOIN public.control_audit_jobs j ON (((j.company_id = h.company_id) AND (j.job_id = h.build_job_id))))
     JOIN public.control_audit_job_intents i ON (((i.company_id = j.company_id) AND (i.id = j.job_id))))
  WHERE ((h.company_id = control_audit_snapshot_index_items.company_id) AND (h.snapshot_id = control_audit_snapshot_index_items.snapshot_id) AND (j.state = 'running'::text) AND (j.generation = h.build_generation) AND (j.lease_id = h.build_lease_id) AND (j.lease_expires_at > clock_timestamp()) AND (i.requester_person_id = auth.uid()))))));


--
-- Name: control_audit_snapshot_indexes tenant_create; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY tenant_create ON public.control_audit_snapshot_indexes FOR INSERT WITH CHECK (((company_id = app.current_company_id()) AND (company_id IN ( SELECT auth.user_companies() AS user_companies)) AND (build_job_id IS NOT NULL) AND (build_generation IS NOT NULL) AND (build_lease_id IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM (public.control_audit_jobs j
     JOIN public.control_audit_job_intents i ON (((i.company_id = j.company_id) AND (i.id = j.job_id))))
  WHERE ((j.company_id = control_audit_snapshot_indexes.company_id) AND (j.job_id = control_audit_snapshot_indexes.build_job_id) AND (j.state = 'running'::text) AND (j.generation = control_audit_snapshot_indexes.build_generation) AND (j.lease_id = control_audit_snapshot_indexes.build_lease_id) AND (j.lease_expires_at > clock_timestamp()) AND (i.requester_person_id = auth.uid()) AND ((i.kind = 'audit_compare'::text) OR ((i.kind = 'audit_snapshot'::text) AND (j.job_id = control_audit_snapshot_indexes.snapshot_id))))))));


