-- Name: control_audit_jobs tenant_worker; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY tenant_worker ON public.control_audit_jobs FOR UPDATE USING (((company_id = app.current_company_id()) AND (company_id IN ( SELECT auth.user_companies() AS user_companies)) AND (EXISTS ( SELECT 1
   FROM public.control_audit_job_intents i
  WHERE ((i.company_id = control_audit_jobs.company_id) AND (i.id = control_audit_jobs.job_id) AND (i.requester_person_id = auth.uid())))))) WITH CHECK (((company_id = app.current_company_id()) AND (company_id IN ( SELECT auth.user_companies() AS user_companies)) AND (EXISTS ( SELECT 1
   FROM public.control_audit_job_intents i
  WHERE ((i.company_id = control_audit_jobs.company_id) AND (i.id = control_audit_jobs.job_id) AND (i.requester_person_id = auth.uid()))))));


